const rawInput = $input.first().json;
const body = rawInput.body ? rawInput.body : rawInput;

const requestId = body.request_id;
const corrections = body.corrections;
const originalRequest = body.original_request;
const incomingRound = body.correction_round || 1;
const newRound = incomingRound + 1;

if (!requestId) {
  return [{ json: {
    request_id: null,
    decision: 'BLOCKED',
    reason: 'MISSING_REQUEST_ID',
    message: 'request_id is required to process a correction.'
  }}];
}

if (!corrections || typeof corrections !== 'object') {
  return [{ json: {
    request_id: requestId,
    decision: 'BLOCKED',
    reason: 'MISSING_CORRECTIONS',
    message: 'corrections object is required.'
  }}];
}

if (!originalRequest || !Array.isArray(originalRequest.items)) {
  return [{ json: {
    request_id: requestId,
    decision: 'BLOCKED',
    reason: 'MISSING_ORIGINAL_REQUEST',
    message: 'original_request is required. In Week 4 this will be fetched from Supabase automatically.'
  }}];
}

// Merge corrections into original request
const mergedRequest = Object.assign({}, originalRequest);

if (corrections.sizes) mergedRequest.sizes = corrections.sizes;
if (corrections.colors) mergedRequest.colors = corrections.colors;
if (corrections.variation_structure) mergedRequest.variation_structure = corrections.variation_structure;
if (corrections.variation_theme) mergedRequest.variation_theme = corrections.variation_theme;
if (corrections.matrix_assignments) mergedRequest.matrix_assignments = corrections.matrix_assignments;
if (corrections.acknowledged_manual_reviews) mergedRequest.acknowledged_manual_reviews = corrections.acknowledged_manual_reviews;


if (Array.isArray(corrections.items)) {
  for (let i = 0; i < corrections.items.length; i++) {
    const corrItem = corrections.items[i];
    const target = mergedRequest.items.find(function(it) {
      return it.sku === corrItem.sku;
    });
    if (target) {
      Object.assign(target, corrItem);
    }
  }
}

return [{ json: {
  request_id: requestId,
  correction_round: newRound,
  decision: 'CORRECTION_MERGED',
  merged_request: mergedRequest
}}];

const previous = $input.first().json;

if (previous.decision === 'BLOCKED') {
  return [{ json: previous }];
}

if (previous.correction_round > 5) {
  const msg = 'This request has gone through 5 correction rounds without resolving all issues. Please review your data and submit a new request.';
  return [{ json: {
    request_id: previous.request_id,
    decision: 'BLOCKED',
    reason: 'MAX_CORRECTION_ROUNDS_EXCEEDED',
    message: msg,
    issues: [{
      issue_code: 'MAX_CORRECTION_ROUNDS_EXCEEDED',
      severity: 'hard_block',
      message: msg,
      can_user_fix: false,
      can_user_override: false
    }],
    correction_round: previous.correction_round
  }}];
}

const merged = previous.merged_request;
const items = merged.items;
const issues = [];
const manualReviews = [];

// Abuse scan
const forbiddenPhrases = [
  'combine reviews', 'merge reviews', 'transfer reviews',
  'boost ranking', 'force merge', 'bypass amazon', 'manipulate reviews'
];
function scanForAbuse(value) {
  if (typeof value !== 'string') return null;
  const lower = value.toLowerCase();
  for (let i = 0; i < forbiddenPhrases.length; i++) {
    if (lower.includes(forbiddenPhrases[i])) return forbiddenPhrases[i];
  }
  return null;
}
for (let i = 0; i < items.length; i++) {
  const found = scanForAbuse(items[i].brand) || scanForAbuse(items[i].sku);
  if (found) {
    const msg = 'Correction contains language associated with policy violation.';
    return [{ json: {
      request_id: previous.request_id,
      decision: 'BLOCKED',
      reason: 'REVIEW_MANIPULATION_INTENT',
      message: msg,
      issues: [{
        issue_code: 'REVIEW_MANIPULATION_INTENT',
        severity: 'hard_block',
        message: msg,
        can_user_fix: false,
        can_user_override: false
      }],
      correction_round: previous.correction_round
    }}];
  }
}

// Brand mismatch
const normalizedBrands = items.map(function(it) { return it.brand.toLowerCase().trim(); });
const firstBrand = normalizedBrands[0];
if (normalizedBrands.some(function(b) { return b !== firstBrand; })) {
  const brandsFound = [...new Set(items.map(function(it) { return it.brand; }))].join(', ');
  const msg = 'All items must belong to the same brand after correction. Found: ' + brandsFound;
  return [{ json: {
    request_id: previous.request_id,
    decision: 'BLOCKED',
    reason: 'BRAND_MISMATCH',
    message: msg,
    issues: [{
      issue_code: 'BRAND_MISMATCH',
      severity: 'hard_block',
      message: msg,
      can_user_fix: false,
      can_user_override: false
    }],
    correction_round: previous.correction_round
  }}];
}

// Product type mismatch
const productTypes = items
  .map(function(it) { return it.product_type ? it.product_type.toUpperCase().trim() : null; })
  .filter(function(pt) { return pt !== null; });
if (productTypes.length > 0) {
  const firstType = productTypes[0];
  if (productTypes.some(function(pt) { return pt !== firstType; })) {
    const typesFound = [...new Set(productTypes)].join(', ');
    const msg = 'All items must have the same product type. Found: ' + typesFound + '. Amazon cannot create a variation relationship between items of different product types.';
    return [{ json: {
      request_id: previous.request_id,
      decision: 'BLOCKED',
      reason: 'PRODUCT_TYPE_MISMATCH',
      message: msg,
      product_types_found: typesFound,
      issues: [{
        issue_code: 'PRODUCT_TYPE_MISMATCH',
        severity: 'hard_block',
        message: msg,
        can_user_fix: false,
        can_user_override: false
      }],
      correction_round: previous.correction_round
    }}];
  }
}

// Unsupported variation theme
const supportedThemes = {
  'CLOTHING': ['Color', 'Size', 'ColorSize', 'SizeColor'],
  'SHOES':    ['Size', 'Color', 'SizeColor'],
  'JEWELRY':  ['Color', 'MetalType']
};
const requestedTheme = merged.variation_theme;
const productType = items[0].product_type ? items[0].product_type.toUpperCase().trim() : null;
if (requestedTheme && productType && supportedThemes[productType]) {
  const allowed = supportedThemes[productType];
  if (!allowed.includes(requestedTheme)) {
    const msg = '"' + requestedTheme + '" is not a supported variation theme for ' + productType + '. Supported themes are: ' + allowed.join(', ') + '. Use real Product Type Definitions API in Week 6 for authoritative schema.';
    return [{ json: {
      request_id: previous.request_id,
      decision: 'BLOCKED',
      reason: 'UNSUPPORTED_VARIATION_THEME',
      message: msg,
      requested_theme: requestedTheme,
      supported_themes: allowed,
      issues: [{
        issue_code: 'UNSUPPORTED_VARIATION_THEME',
        severity: 'hard_block',
        message: msg,
        can_user_fix: false,
        can_user_override: false
      }],
      correction_round: previous.correction_round
    }}];
  }
}

// Manual review — category mismatch
const categories = items
  .map(function(it) { return it.category ? it.category.trim() : null; })
  .filter(function(c) { return c !== null; });
if (categories.length > 0) {
  const firstCat = categories[0];
  const catMismatch = categories.some(function(c) { return c !== firstCat; });
  if (catMismatch) {
    const catsFound = [...new Set(categories)].join(', ');
    manualReviews.push({
      issue_code: 'CATEGORY_MISMATCH',
      severity: 'manual_review',
      message: 'These items are in different Amazon categories: ' + catsFound + '. Review whether merging them is appropriate before continuing.',
      categories_found: catsFound,
      question_to_user: 'Items span multiple categories (' + catsFound + '). Are you sure these belong in the same variation family?',
      can_user_fix: false,
      can_user_override: true
    });
  }
}

// Manual review — existing parent conflict
const intendedParent = merged.intended_parent_sku || null;
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  if (item.parent_sku && intendedParent && item.parent_sku !== intendedParent) {
    manualReviews.push({
      issue_code: 'EXISTING_PARENT_CONFLICT',
      severity: 'manual_review',
      sku: item.sku,
      existing_parent: item.parent_sku,
      intended_parent: intendedParent,
      message: item.sku + ' already belongs to parent ' + item.parent_sku + '. You must remove it from that family before adding it here.',
      question_to_user: 'SKU ' + item.sku + ' is currently in parent family ' + item.parent_sku + '. Do you want to move it to the new parent?',
      can_user_fix: false,
      can_user_override: true
    });
  }
}

// Return manual reviews if any exist and not yet acknowledged
if (manualReviews.length > 0 && !merged.acknowledged_manual_reviews) {
  return [{ json: {
    request_id: previous.request_id,
    decision: 'MANUAL_REVIEW',
    issue_summary: manualReviews.length + ' item(s) require your review before continuing.',
    manual_reviews: manualReviews,
    issues: manualReviews,
    next_action: 'Re-submit with acknowledged_manual_reviews: true in your corrections to proceed.',
    correction_round: previous.correction_round,
    merged_request: merged
  }}];
}

// Formatting issues
const formattingMap = {
  'extra large':  { canonical: 'XL',         field: 'size'  },
  'extra-large':  { canonical: 'XL',         field: 'size'  },
  'large':        { canonical: 'L',          field: 'size'  },
  'medium':       { canonical: 'M',          field: 'size'  },
  'small':        { canonical: 'S',          field: 'size'  },
  'dark red':     { canonical: 'Dark Red',   field: 'color' },
  'dark_red':     { canonical: 'Dark Red',   field: 'color' },
  'light blue':   { canonical: 'Light Blue', field: 'color' },
  'light_blue':   { canonical: 'Light Blue', field: 'color' }
};
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const val = item.variation_value;
  if (typeof val === 'string') {
    const match = formattingMap[val.toLowerCase().trim()];
    if (match && val !== match.canonical) {
      issues.push({
        issue_code: 'FORMATTING_ISSUE',
        severity: 'fixable',
        sku: item.sku,
        current_value: val,
        suggested_value: match.canonical,
        field: match.field,
        message: item.sku + ' has variation_value "' + val + '" which is not Amazon standard format.',
        question_to_user: 'We noticed ' + item.sku + ' has value "' + val + '". Did you mean "' + match.canonical + '"? (Amazon standard format). Please confirm or provide the correct value.',
        can_user_fix: true,
        can_user_override: false
      });
    }
  }
}

// Missing variation values
if (merged.variation_structure === 'single_theme') {
  for (let i = 0; i < items.length; i++) {
    if (!items[i].variation_value) {
      issues.push({
        issue_code: 'MISSING_VARIATION_VALUE',
        severity: 'fixable',
        sku: items[i].sku,
        message: items[i].sku + ' is still missing its variation value after correction.',
        question_to_user: 'Please enter the variation value for ' + items[i].sku + '.',
        can_user_fix: true,
        can_user_override: false
      });
    }
  }
}

if (issues.length > 0) {
  return [{ json: {
    request_id: previous.request_id,
    decision: 'NEEDS_INPUT',
    issue_summary: issues.length + ' issue(s) still need your input after correction.',
    issue_diagnosis: issues,
    correction_round: previous.correction_round,
    merged_request: merged
  }}];
}

return [{ json: {
  request_id: previous.request_id,
  decision: 'CAN_CONTINUE_TO_DRY_RUN',
  message: 'All corrections applied. Validation passed. Ready to continue.',
  correction_round: previous.correction_round,
  merged_request: merged
}}];

const prev = $input.first().json;
const issueList = prev.issue_diagnosis || prev.issues || [];
return [{ json: {
  _original_payload: prev,
  request_id: prev.request_id,
  decision: prev.decision,
  reason_code: prev.reason_code || issueList[0]?.issue_code || null,
  issue_summary: prev.issue_summary || null,
  hard_blocks_json: JSON.stringify(
    issueList.filter(i => i.severity === 'hard_block')
  ),
  raw_result_json: JSON.stringify(prev),
  issues_json: JSON.stringify(issueList),
  next_action: prev.next_action || null
}}];

const prev = $input.first().json;
const body = $('Correction Merger').first().json;

const corrections = body.merged_request 
  ? body : 
  { corrections: {} };

return [{ json: {
  _original_payload: prev,
  request_id: prev.request_id,
  round_number: body.correction_round || 1,
  corrections_json: JSON.stringify(
    corrections.merged_request || {}
  ),
  revalidation_result: prev.decision
}}];
